using Microsoft.EntityFrameworkCore; namespace TrootWindow.Api.Data; public sealed class AppDbContext(DbContextOptions<AppDbContext> o):DbContext(o){public DbSet<Job> Jobs=>Set<Job>(); protected override void OnModelCreating(ModelBuilder b){b.Entity<Job>().HasKey(x=>x.Id);b.Entity<Job>().HasIndex(x=>new{x.Status,x.CreatedAt});b.Entity<Job>().Property(x=>x.Mode).HasConversion<string>();b.Entity<Job>().Property(x=>x.Status).HasConversion<string>();}}